+import { expect, test } from 'vitest'
+import { RateLimiter } from './rateLimiter'
+
+const options = { maxAttempts: 3, windowMs: 1000, lockoutMs: 5000 }
+
+function setup() {
+  let now = 0
+  const clock = { now: () => now }
+  const limiter = new RateLimiter(options, clock)
+  return { limiter, advance: (ms: number) => (now += ms) }
+}
+
+test('allows attempts up to the limit', () => {
+  const { limiter } = setup()
+  expect(limiter.check('a')).toEqual({ allowed: true, remaining: 2 })
+  expect(limiter.check('a')).toEqual({ allowed: true, remaining: 1 })
+  expect(limiter.check('a')).toEqual({ allowed: true, remaining: 0 })
+})
+
+test('locks the key out after too many attempts', () => {
+  const { limiter, advance } = setup()
+  for (let i = 0; i < 3; i++) limiter.check('a')
+  expect(limiter.check('a')).toEqual({ allowed: false, retryAt: 5000 })
+  advance(5001)
+  expect(limiter.check('a').allowed).toBe(true)
+})
