+++ b/src/auth/rateLimiter.ts
@@ -0,0 +1,56 @@
+import { systemClock, type Clock } from '../utils/time'
+
+export interface RateLimitOptions {
+  maxAttempts: number
+  windowMs: number
+  lockoutMs: number
+}
+
+export type RateLimitResult =
+  | { allowed: true; remaining: number }
+  | { allowed: false; retryAt: number }
+
+interface Bucket {
+  attempts: number[]
+  lockedUntil: number
+}
+
+export class RateLimiter {
+  private buckets = new Map<string, Bucket>()
+
+  constructor(
+    private options: RateLimitOptions,
+    private clock: Clock = systemClock,
+  ) {}
+
+  /** Records one attempt for `key` and reports whether it may proceed. */
+  check(key: string): RateLimitResult {
+    const now = this.clock.now()
+    const bucket = this.buckets.get(key) ?? { attempts: [], lockedUntil: 0 }
+    this.buckets.set(key, bucket)
+
+    if (bucket.lockedUntil > now) {
+      return { allowed: false, retryAt: bucket.lockedUntil }
+    }
+
+    const windowStart = now - this.options.windowMs
+    bucket.attempts = bucket.attempts.filter((t) => t > windowStart)
+    bucket.attempts.push(now)
+
+    if (bucket.attempts.length > this.options.maxAttempts) {
+      bucket.lockedUntil = now + this.options.lockoutMs
+      bucket.attempts = []
+      return { allowed: false, retryAt: bucket.lockedUntil }
+    }
+
+    return {
+      allowed: true,
+      remaining: this.options.maxAttempts - bucket.attempts.length,
+    }
+  }
+
+  /** Forgets all attempts for `key`, called after a successful login. */
+  reset(key: string): void {
+    this.buckets.delete(key)
+  }
+}
