+
+/** Signs the user out everywhere, used after a password change. */
+export function destroyUserSessions(userId: string): number {
+  let removed = 0
+  for (const [id, session] of sessions) {
+    if (session.userId === userId) {
+      sessions.delete(id)
+      removed++
+    }
+  }
+  return removed
+}
