@@ -0,0 +1,12 @@
+/** Wall clock, wrapped so tests can freeze it. */
+export interface Clock {
+  now(): number
+}
+
+export const systemClock: Clock = {
+  now: () => Date.now(),
+}
+
+export function secondsUntil(timestamp: number, clock: Clock = systemClock): number {
+  return Math.max(0, Math.ceil((timestamp - clock.now()) / 1000))
+}
